// GR Error Handler safe extraction + throttle so a 100%-failure loop can't spam you .
const e   = ($input.first() && $input.first().json) || {};
const wf  = e.workflow || {};
const ex  = e.execution || {};
const err = (ex.error || e.error || {});

const node    = (err.node && err.node.name) || ex.lastNodeExecuted || 'unknown node';
const message = (err.message || 'unknown error').toString();
const mode    = ex.mode || 'unknown';
const url     = ex.url || '';
const now     = Date.now();
const WINDOW_MS = 15 * 60 * 1000; // suppress repeats of the SAME failure for 15 min

const fingerprint = [wf.id || wf.name || '?', node, message.slice(0, 120)].join('|');

// remember what we've alerted on, using n8n's built-in static data (no external store needed)
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
for (const k of Object.keys(sd.seen)) {            // prune entries older than 24h
  if (now - ((sd.seen[k] && sd.seen[k].last) || 0) > 24 * 60 * 60 * 1000) delete sd.seen[k];
}
const prev     = sd.seen[fingerprint];
const suppress = !!(prev && (now - prev.last) < WINDOW_MS);
const count    = (prev ? prev.count : 0) + 1;
sd.seen[fingerprint] = { first: prev ? prev.first : now, last: now, count };

const ts        = new Date(now).toISOString();
const repeatTag = count > 1 ? ` (x${count})` : '';
const slack_text =
  `:rotating_light: *GR error* in *${wf.name || 'unknown'}*${repeatTag}\n` +
  `> node: *${node}*\n> ${message}\n> mode: ${mode}` + (url ? `\n> ${url}` : '');
const telegram_text =
  ` GR error - ${wf.name || 'unknown'}${repeatTag}\n\n` +
  `- node: ${node}\n- ${message}\n- mode: ${mode}` + (url ? `\n- ${url}` : '');

return [{ json: {
  alert: !suppress, suppressed: suppress, count, fingerprint,
  workflow_name: wf.name || 'unknown', workflow_id: wf.id || '',
  failed_node: node, error_message: message, mode, execution_url: url, ts,
  slack_text, telegram_text
}}];

const ALWAYS_KEEP = new Set(['n8n Blog', 'Zapier Blog', 'OpenAI']);
const PER_FEED_CAP = 25;
const PILLAR_KEYWORDS = [
  'ai', 'llm', 'gpt', 'anthropic', 'claude', 'openai', 'chatgpt', 'gemini', 'model', 'agent', 'copilot', 'mcp', 'prompt', 'rag',
  'automat', 'workflow', 'integrat', 'api', 'webhook', 'orchestrat', 'idempoten', 'pipeline', 'etl', 'rpa', 'trigger', 'node',
  'zapier', 'n8n', 'make.com', 'no code', 'low code', 'airtable', 'cal.com', 'notion', 'obsidian', 'google sheets', 'slack', 'telegram',
  'system', 'database', 'postgres', 'supabase', 'firebase', 'backend', 'credential', 'rbac', 'versioning', 'observability', 'reliab', 'monitor', 'security', 'soc 2', 'compliance', 'self host',
  'business', 'operation', 'process', 'sop', 'standard operating', 'crm', 'onboarding', 'invoic', 'billing', 'revenue', 'client', 'customer', 'lead', 'sales', 'funnel', 'systeme', 'quickbooks', 'bookkeeping', 'accounting', 'cpq', 'dashboard', 'kpi', 'productivit', 'project management', 'saas', 'subscription'
];
const BLOCKLIST = [
  'deal', 'deals', 'sale', 'discount', 'coupon', 'printer', 'printers', 'earbud', 'earbuds', 'headphone', 'headphones',
  'smartphone', 'smartphones', 'iphone', 'ipad', 'tablet', 'wearable', 'smartwatch', 'gadget', 'gadgets', 'doorbell',
  'rideshare', 'uber', 'lyft', 'movie', 'movies', 'film', 'films', 'thriller', 'hollywood', 'celebrity', 'celebrities',
  'nintendo', 'playstation', 'xbox', 'console', 'unboxing', '3d printer', 'box office', 'gift guide', 'folding phone'
];

const normText = (s) => (' ' + String(s || '').toLowerCase().replace(/[^a-z0-9. ]+/g, ' ').replace(/\s+/g, ' ').trim() + ' ');
const isPhrase = (k) => k.indexOf(' ') >= 0 || k.indexOf('.') >= 0;
const pillarHit = (hay, tokens) => PILLAR_KEYWORDS.some((k) => isPhrase(k) ? hay.indexOf(' ' + k + ' ') >= 0 : tokens.some((t) => t.startsWith(k)));
const blockHit = (hay, tokenSet) => BLOCKLIST.some((k) => isPhrase(k) ? hay.indexOf(' ' + k + ' ') >= 0 : tokenSet.has(k));

const toManila = (val) => { const d = new Date(val); if (isNaN(d)) return ''; return d.toLocaleString('sv-SE', { timeZone: 'Asia/Manila' }); };

const existing = new Set($('Get row(s) in sheet').all().map((i) => i.json.link).filter(Boolean));
const cleanLink = (u) => { try { const x = new URL(String(u)); x.search = ''; x.hash = ''; return x.toString(); } catch (e) { return String(u || ''); } };

const feed = $('Merge feeds').all();
const bySource = new Map();

for (const item of feed) {
  const j = item.json || {};
  const link = cleanLink(j.link || j.guid || '');
  if (!link || existing.has(link)) continue;
  existing.add(link);

  const title = (j.title || '').toString().trim();
  const rawBody = [j['content:encoded'], j.content, j['content:encodedSnippet'], j.contentSnippet, title]
    .filter(Boolean)
    .map((s) => s.toString().replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim())
    .sort((a, b) => b.length - a.length)[0] || '';
  const source = j.source || 'Unknown';

  const hay = normText(title + ' ' + rawBody);
  const tokens = hay.trim().split(' ');
  const tokenSet = new Set(tokens);

  if (blockHit(hay, tokenSet)) continue;
  if (!ALWAYS_KEEP.has(source) && !pillarHit(hay, tokens)) continue;

  const source_text = rawBody.slice(0, 400) + (rawBody.length > 400 ? '...' : '');
  const llm_body = rawBody.slice(0, 1500);
  const rawDate = j.isoDate || j.pubDate || '';
  const pub_ts = Date.parse(rawDate) || 0;

  if (!bySource.has(source)) bySource.set(source, []);
  bySource.get(source).push({ json: { title, link, source, pub_date: toManila(rawDate), pub_ts, source_text, llm_body } });
}

for (const [src, arr] of bySource) {
  arr.sort((a, b) => (b.json.pub_ts || 0) - (a.json.pub_ts || 0));
  if (arr.length > PER_FEED_CAP) bySource.set(src, arr.slice(0, PER_FEED_CAP));
}

const buckets = [...bySource.values()];
const out = [];
let added = true;
while (added) { added = false; for (const b of buckets) { if (b.length) { out.push(b.shift()); added = true; } } }
return out;

// Split model output into pillar / graphic_caption / caption / hashtags. Runs over all items.
// Fast path: JSON.parse (handles flat string arrays AND valid {"list":[...]} blocks).
// Fallback: if JSON is invalid (the weak model sometimes jams a paragraph inside a list
// object -> invalid JSON), SALVAGE the fields by pulling the quoted strings out directly,
// so a broken row still yields a usable caption instead of a raw-JSON dump.
const out = [];
const items = $input.all();
const NL = String.fromCharCode(10);
const ARROW = String.fromCharCode(8594);
function normLine(s){ s = String(s == null ? '' : s).trim(); return s.replace(/^\s*[-*\u2022\u2192]\s+/, ARROW + ' '); }
function renderLines(flat){
  const blocks = []; let buf = [];
  flat.forEach(function(s){ if (!s) return; if (s.charAt(0) === ARROW) { buf.push(s); } else { if (buf.length){ blocks.push(buf.join(NL)); buf=[]; } blocks.push(s); } });
  if (buf.length) blocks.push(buf.join(NL));
  return blocks.join(NL + NL);
}
function cleanTags(tags){
  const clean = tags.map(function(t){ return '#' + String(t||'').replace(/^#+/,'').replace(/[^A-Za-z0-9]/g,''); }).filter(function(x){ return x.length > 1; });
  if (clean.map(function(t){ return t.toLowerCase(); }).indexOf('#thegrframework') < 0) clean.push('#TheGRFramework');
  const seen = {}; const uniq = [];
  clean.forEach(function(t){ const k = t.toLowerCase(); if (!seen[k]) { seen[k] = 1; uniq.push(t); } });
  return uniq.slice(0, 8).join(' ');
}
for (let i = 0; i < items.length; i++) {
  let raw = (items[i].json.text == null ? '' : items[i].json.text).toString();
  raw = raw.replace(/```+\s*json/gi, '').replace(/```+/g, '').trim();
  let pillar = '', graphic_caption = '', caption = '', hashtags = '';
  try {
    const m = raw.match(/\{[\s\S]*\}/);
    let js = (m ? m[0] : raw).replace(/,\s*([}\]])/g, '$1');
    const o = JSON.parse(js);
    pillar = (o.pillar || '').toString().trim().toUpperCase();
    graphic_caption = (o.graphic_caption || '').toString().trim();
    let arr = Array.isArray(o.caption) ? o.caption : [o.caption];
    let flat = [];
    arr.forEach(function(x){ if (x && typeof x === 'object' && Array.isArray(x.list)) { x.list.forEach(function(it){ flat.push(ARROW + ' ' + String(it || '').trim()); }); } else { const s = normLine(x); if (s) flat.push(s); } });
    caption = renderLines(flat);
    const tags = Array.isArray(o.hashtags) ? o.hashtags : (o.hashtags ? String(o.hashtags).split(/[\s,]+/) : []);
    hashtags = cleanTags(tags);
  } catch (e) {
    const pm = raw.match(/"pillar"\s*:\s*"([^"]*)"/i);
    const gm = raw.match(/"graphic_caption"\s*:\s*"([^"]*)"/i);
    pillar = pm ? pm[1].trim().toUpperCase() : '';
    graphic_caption = gm ? gm[1].trim() : '';
    let cstart = raw.search(/"caption"\s*:/);
    let region = cstart >= 0 ? raw.slice(cstart) : raw;
    let hstart = region.search(/"hashtags"\s*:/);
    if (hstart >= 0) region = region.slice(0, hstart);
    let lines = []; let re = /"([^"]*)"/g; let mm;
    while ((mm = re.exec(region)) !== null) {
      let s = mm[1].trim();
      if (!s) continue;
      const low = s.toLowerCase();
      if (low === 'list' || low === 'caption' || low === 'pillar' || low === 'graphic_caption' || low === 'hashtags') continue;
      if (s.charAt(0) === '#') continue;
      lines.push(normLine(s));
    }
    caption = renderLines(lines);
    hashtags = cleanTags(raw.match(/#[A-Za-z0-9]+/g) || []);
  }
  if (['SYSTEMS','AUTOMATION','BUSINESS','TECH'].indexOf(pillar) < 0) pillar = '';
  out.push({ json: { pillar, graphic_caption, caption, hashtags }, pairedItem: { item: i } });
}
return out;

