// Do the whole 'pick the next post' step in code so it never depends on the
// Google Sheets filter dropdown (which fails to bind on import -> returns every
// row unfiltered). Two steps:
//  1) FILTER: keep only rows whose status is exactly Approved (trimmed +
//     case-tolerant), so Pending/Posting/Posted/Posted-FB/Failed-FB are excluded.
//  2) ORDER: sort by post_order NUMERICALLY. organizeQueue() numbers rows with
//     Number() (1,2,3,...); a string sort would put "10" before "2". Blank /
//     non-numeric post_order sorts last. Limit (next node) then takes the top.
const isApproved = (it) => String(it.json.status ?? '').trim().toLowerCase() === 'approved';
const key = (it) => {
  const v = it.json.post_order;
  const n = Number(v);
  return (v === '' || v === null || v === undefined || Number.isNaN(n)) ? Infinity : n;
};
return $input.all().filter(isApproved).sort((a, b) => key(a) - key(b));
